// lazytopper/src/data/bankFix/pyqRestoreBLedger.ts
//
// PYQ-RESTORE-B (2026-10-23) - the provenance ledger for PYQ rows that could only be repaired by READING THE
// OFFICIAL PAPER again (the "B" rows of the PYQ-RESTORE audit: missing / cut text, figures, wrong or disputed
// keys, Hindi-column or mojibake stems to re-extract in English). Mirrors pyqRestore1Ledger.ts.
//
// OWNER APPROVAL (22 Oct 2026, 23:15 IST): downloading the official CBSE papers and marking schemes, editing
// question data under src/data/, adding PYQ files and figure files. Owner figure ruling: reuse a bound figure
// named after the row when one exists (opened once to confirm), otherwise crop it from the official paper page.
//
// METHOD (PR-1, Maths). Every row was located in the official CBSE Mathematics Standard (041) question paper
// named by its `ref` (30/x/y; 30(B) = the paper for visually impaired candidates) from the official zips on
// cbse.gov.in, and read from the text layer AND a render of the page (the text layer drops minus signs, θ, √,
// ∆, ∠ and fraction bars, which the papers draw as vectors). The answer and the "[N mark]" step split come from
// the OFFICIAL marking scheme of the same paper (`ms`); objective items carry one "[1 mark]" step. Each row was
// then re-solved blind from its served stem (and figure); a row whose re-solve disagreed with the scheme would
// have stayed withheld (none did). Syllabus 2026-27 checked per row against scripts/src/syllabusGuard.ts and
// config/syllabus2026-27.ts; the one OUT part met (PYQ-M-2026-TRI-005 OR (iii)(b), area ratio of similar
// triangles) is not carried. SHA-256 is of the inner PDF; every one matches the hash PYQ-RESTORE-1 /
// REFILE-PYQ2026-1 recorded for the same file. Papers live outside the repo.
//   verdict "restored" - a withheld or "others"-filed row, repaired from the paper and served again as a PYQ.
//   verdict "added"    - a new row of maths/triangles.pyq2025.ts (the 2025 Triangles questions the other
//                        *.pyq2025.ts files never carried); `fix` names the other sets that print it.
//   figure "new"       - cropped at 200 dpi from the official page (or the paper's embedded image), bound in
//                        figures/mathsFigureVisuals.ts; "reused" - the figure already bound to this id.
// Row ids are never changed (Mistake Intelligence history keys on them).

export interface PyqRestoreBEntry {
  id: string;
  verdict: "restored" | "added";
  /** The row's paper reference (its `ncertRef`). */
  ref: string;
  year: string;
  set: string;
  /** Official question paper: zip URL#inner path, and the SHA-256 of that inner PDF. */
  qp: string;
  qpSha256: string;
  /** Official marking scheme for the same paper. */
  ms: string;
  msSha256: string;
  /** The "[N mark]" prefixes of the served row, in step order (they sum to its marks). */
  stepMarks: readonly number[];
  figure?: "new" | "reused";
  figurePath?: string;
  fix: string;
  /** The marking-scheme answer and the blind re-solve that agreed with it. */
  verify: string;
}

